def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping intervals in b
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    b_merged = merge_intervals(b)

    # Merge overlapping intervals in a
    a_merged = merge_intervals(a)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = a_start
        for b_start, b_end in b_merged:
            if b_end <= current or b_start >= a_end:
                # b interval doesn't overlap with current range
                continue
            if b_start > current:
                # Add the gap before b
                result.append([current, b_start])
            # Move current past the b interval
            current = max(current, b_end)
        if current < a_end:
            # Add any remaining part
            result.append([current, a_end])

    # Merge touching intervals in result
    if result:
        result = merge_intervals(result)

    return result

